//! Build-time directory registry, following the existing dispatch directory mounts.
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

pub fn render(programs: &[PathBuf]) -> Result<String, String> {
    if programs.len() > 64 {
        return Err("NPC program registry exceeds 64 documents".into());
    }
    let mut programs = programs.to_vec();
    programs.sort();
    if programs.windows(2).any(|pair| pair[0] == pair[1]) {
        return Err("duplicate NPC program path".into());
    }
    let mut result = String::from(
        "// @generated by crates/gameplay/quests/build_npc_programs.rs\n\
         pub(super) const NPC_RULE_PROGRAMS: &[&str] = &[\n",
    );
    for path in programs {
        let name = path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or("NPC filename is not UTF-8")?;
        let Some(stem) = name
            .strip_prefix("quest-batch3-")
            .or_else(|| name.strip_prefix("quest-authored-"))
            .and_then(|name| name.strip_suffix(".json"))
        else {
            return Err(format!("unreviewed NPC program filename: {name}"));
        };
        if stem.is_empty()
            || !stem
                .bytes()
                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, b'-' | b'_'))
        {
            return Err(format!("invalid NPC program filename: {name}"));
        }
        let path = path.to_str().ok_or("NPC program path is not UTF-8")?;
        writeln!(result, "    include_str!({path:?}),").map_err(|error| error.to_string())?;
    }
    result.push_str("];\n");
    Ok(result)
}

pub fn generate(root: &Path, out: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let directory = root.join("../../../content/dialogues/quest-rules");
    println!("cargo:rerun-if-changed={}", directory.display());
    let mut programs = Vec::new();
    let mut authored = Vec::new();
    if directory.exists() {
        for entry in std::fs::read_dir(&directory)? {
            let entry = entry?;
            let path = entry.path();
            if entry.file_type()?.is_file()
                && path
                    .extension()
                    .is_some_and(|extension| extension == "json")
                && path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| {
                        name.starts_with("quest-batch3-") || name.starts_with("quest-authored-")
                    })
            {
                println!("cargo:rerun-if-changed={}", path.display());
                if path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| name.starts_with("quest-authored-"))
                {
                    authored.push(path);
                } else {
                    programs.push(path);
                }
            }
        }
    }
    std::fs::write(out.join("npc_rule_programs.rs"), render(&programs)?)?;
    std::fs::write(
        out.join("authored_npc_rule_programs.rs"),
        render(&authored)?.replace("NPC_RULE_PROGRAMS", "AUTHORED_NPC_RULE_PROGRAMS"),
    )?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_registry_needs_no_quest_file() -> Result<(), String> {
        let result = render(&[])?;
        assert!(result.contains("const NPC_RULE_PROGRAMS"));
        assert!(!result.contains("include_str!"));
        Ok(())
    }

    #[test]
    fn absent_source_directory_generates_a_valid_empty_registry()
    -> Result<(), Box<dyn std::error::Error>> {
        let scratch =
            std::env::temp_dir().join(format!("oteryn-npc-registry-{}", std::process::id()));
        let root = scratch.join("crates/gameplay/quests");
        let out = scratch.join("generated");
        std::fs::create_dir_all(&root)?;
        std::fs::create_dir_all(&out)?;
        generate(&root, &out)?;
        let actual = std::fs::read_to_string(out.join("npc_rule_programs.rs"))?;
        std::fs::remove_dir_all(scratch)?;
        assert_eq!(actual, render(&[])?);
        Ok(())
    }

    #[test]
    fn each_added_program_is_mounted_in_stable_order() -> Result<(), String> {
        let first = PathBuf::from("/source/quest-batch3-a-first.json");
        let second = PathBuf::from("/source/quest-batch3-b-second.json");
        let rendered = render(&[second.clone(), first.clone()])?;
        assert_eq!(rendered, render(&[first.clone(), second.clone()])?);
        assert_eq!(rendered.matches("include_str!").count(), 2);
        assert!(
            rendered.find("a-first").ok_or("missing first")?
                < rendered.find("b-second").ok_or("missing second")?
        );
        assert!(render(&[first.clone(), first]).is_err());
        assert!(render(&[PathBuf::from("/source/unreviewed.json")]).is_err());
        Ok(())
    }
}
